import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    words = sorted(data[1:1+n])
    valid = {''}
    best = ''
    for w in words:
        if w[:-1] in valid:
            valid.add(w)
            if len(w) > len(best) or (len(w) == len(best) and w < best):
                best = w
    print(best)
